import React, { useState } from 'react';

function App() {
  const [curr, changefun] = useState()
  const name = '';
  const press = (event)=>{
    name = event.target.value;
  };

  const submit = () => {
    let text = "Hello" + "," + name;
  };

  return (
    <>
      <div className='main'>
        <div className='textarea'>
            {"Hello"}
        </div>
        <input type='text' placeholder='Enter Your Name' 
        onChange={press} className='input'/>
        <button onClick={submit} className='btn'>Submit</button>
      </div>
    </>
  );
}

export default App;
